import os

xor = lambda a, b: bytes(x ^ y for x, y in zip(a, b * (len(a)//len(b) + 1)))

class HSM:
    """Holds the KEK. Performs operations, never hands the key back."""
    def __init__(self):
        self._kek = os.urandom(32)
        self.log = []
    def unwrap(self, wrapped, caller):
        self.log.append({"caller": caller, "op": "unwrap"})
        return xor(wrapped, self._kek)
    def rotate(self):
        old, self._kek = self._kek, os.urandom(32)
        return old

hsm = HSM()
STORE = {}
for name, value in [("db/password", b"prod-db-pw-9f2a"),
                    ("stripe/key",  b"sk-live-9f2a")]:
    dek = os.urandom(32)
    STORE[name] = {"ciphertext": xor(value, dek),
                   "wrapped_dek": xor(dek, hsm._kek)}

def read_secret(name, caller):
    e = STORE[name]
    return xor(e["ciphertext"], hsm.unwrap(e["wrapped_dek"], caller))

print("normal operation:", read_secret("db/password", "app-server").decode())
EOF
